using UnityEngine;
using UnityEditor;

public class AssignFallbackIcons
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();
        string basePath = "Assets/Herbal/";

        void AssignFallback(string recipeName, string fallbackIconName)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(basePath + "Recipes/" + recipeName + ".asset");
            var icon = AssetDatabase.LoadAssetAtPath<Sprite>(basePath + fallbackIconName + ".png");
            if (recipe != null && icon != null)
            {
                recipe.recipeImage = icon;
                EditorUtility.SetDirty(recipe);
                sb.AppendLine("[OK] Assigned fallback " + fallbackIconName + " to " + recipeName);
            }
        }

        AssignFallback("Jamu Jahe", "AntiMualIcon");
        AssignFallback("Jamu Kencur", "PernapasanIcon");
        AssignFallback("Jamu Kunyit", "PenurunPanasIcon");
        AssignFallback("Jamu Temulawak", "StaminaIcon");
        AssignFallback("Wedang Jahe", "WedangHerbalIcon");

        AssetDatabase.SaveAssets();
        return sb.ToString();
    }
}
